actions.script:
import java.util.zip.ZipOutputStream import java.util.zip.ZipEntry
def baos = new ByteArrayOutputStream() def zos = new ZipOutputStream(baos)
def addEntry = { name, content -> zos.putNextEntry(new ZipEntry(name)) zos.write(content.getBytes("UTF-8")) zos.closeEntry() }
addEntry("[Content_Types].xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"> <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/> <Default Extension="xml" ContentType="application/xml"/> <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/> <Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/> <Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/> </Types>""")
addEntry("_rels/.rels", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"> <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/> </Relationships>""")
addEntry("xl/workbook.xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"> <sheets> <sheet name="Journal History" sheetId="1" r:id="rId1"/> </sheets> </workbook>""")
addEntry("xl/_rels/workbook.xml.rels", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"> <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/> <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/> </Relationships>""")
addEntry("xl/styles.xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"> <numFmts count="2"> <numFmt numFmtId="164" formatCode="dd/mm/yyyy"/> <numFmt numFmtId="165" formatCode="#,##0.00"/> </numFmts> <fonts count="2"> <font><name val="Calibri"/><sz val="11"/></font> <font><name val="Calibri"/><sz val="11"/><b/><color rgb="FFFFFFFF"/></font> </fonts> <fills count="2"> <fill><patternFill patternType="none"/></fill> <fill><patternFill patternType="solid"><fgColor rgb="FF1A237E"/></patternFill></fill> </fills> <borders count="1"> <border><left/><right/><top/><bottom/><diagonal/></border> </borders> <cellXfs count="4"> <xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/> <xf numFmtId="0" fontId="1" fillId="1" borderId="0" xfId="0" applyFont="1" applyFill="1"/> <xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/> <xf numFmtId="165" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/> </cellXfs> </styleSheet>""")
def sheetXml = new StringBuilder() sheetXml.append("""<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"> <cols> <col min="1" max="1" width="15" customWidth="1"/> <col min="2" max="2" width="15" customWidth="1"/> <col min="3" max="3" width="35" customWidth="1"/> <col min="4" max="4" width="30" customWidth="1"/> <col min="5" max="5" width="30" customWidth="1"/> <col min="6" max="6" width="15" customWidth="1"/> <col min="7" max="7" width="12" customWidth="1"/> </cols> <sheetData> <row r="1"> <c r="A1" s="1" t="inlineStr"><is><t>Journal ID</t></is></c> <c r="B1" s="1" t="inlineStr"><is><t>Date</t></is></c> <c r="C1" s="1" t="inlineStr"><is><t>Description</t></is></c> <c r="D1" s="1" t="inlineStr"><is><t>Debit Account(s)</t></is></c> <c r="E1" s="1" t="inlineStr"><is><t>Credit Account(s)</t></is></c> <c r="F1" s="1" t="inlineStr"><is><t>Amount</t></is></c> <c r="G1" s="1" t="inlineStr"><is><t>Posted</t></is></c> </row> """)
def escapeXml = { str -> if (!str) return "" return str.toString().replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&apos;") }
def rowIndex = 2 def calZone = Calendar.getInstance()
for (row in journalList) { def entries = ec.entity.find("mantle.ledger.transaction.AcctgTransEntry").condition("acctgTransId", row.acctgTransId).list() def debitAccounts = "" def creditAccounts = "" def totalAmount = 0.0 for (ent in entries) { def glAcc = ec.entity.find("mantle.ledger.account.GlAccount").condition("glAccountId", ent.glAccountId).one() def accName = glAcc ? glAcc.accountName : "" if (ent.debitCreditFlag == 'D') { debitAccounts += (debitAccounts ? ', ' : '') + accName totalAmount += (ent.amount ?: 0.0) } else if (ent.debitCreditFlag == 'C') { creditAccounts += (creditAccounts ? ', ' : '') + accName } }
def dateNum = "" if (row.transactionDate) { def ms = row.transactionDate.getTime() def offset = calZone.getTimeZone().getOffset(ms) def days = ((ms + offset) / 86400000.0) + 25569.0 dateNum = """<c r="B${rowIndex}" s="2"><v>${days}</v></c>""" } else { dateNum = """<c r="B${rowIndex}"><v></v></c>""" }
def postedStr = row.isPosted == 'Y' ? 'Yes' : 'No'
sheetXml.append(""" <row r="${rowIndex}"> <c r="A${rowIndex}" t="inlineStr"><is><t>${escapeXml(row.acctgTransId)}</t></is></c> ${dateNum} <c r="C${rowIndex}" t="inlineStr"><is><t>${escapeXml(row.description)}</t></is></c> <c r="D${rowIndex}" t="inlineStr"><is><t>${escapeXml(debitAccounts)}</t></is></c> <c r="E${rowIndex}" t="inlineStr"><is><t>${escapeXml(creditAccounts)}</t></is></c> <c r="F${rowIndex}" s="3"><v>${totalAmount}</v></c> <c r="G${rowIndex}" t="inlineStr"><is><t>${escapeXml(postedStr)}</t></is></c> </row> """) rowIndex++ }
sheetXml.append(""" </sheetData> </worksheet>""")
addEntry("xl/worksheets/sheet1.xml", sheetXml.toString()) zos.close()
ec.web.response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet") ec.web.response.setHeader("Content-Disposition", "attachment; filename=\"Journal_History.xlsx\"") def outStream = ec.web.response.outputStream outStream.write(baos.toByteArray()) outStream.flush()
